<?php
namespace App\Http\Controllers;
use App\Models\{Asset,Category,Location,Ticket,TicketStatusHistory,User};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class TicketController extends Controller {
 public function index(Request $r){$tickets=Ticket::with(['reporter','technician','category','location'])->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest()->paginate(15)->withQueryString();return view('tickets.index',compact('tickets'));}
 public function create(){return view('tickets.create',['categories'=>Category::where('type','ticket')->get(),'locations'=>Location::orderBy('name')->get(),'assets'=>Asset::orderBy('name')->get()]);}
 public function store(Request $r){$data=$r->validate(['title'=>'required|max:255','description'=>'required','priority'=>'required|in:low,medium,high,critical','category_id'=>'nullable|exists:categories,id','location_id'=>'nullable|exists:locations,id','asset_id'=>'nullable|exists:assets,id']);$data['reporter_id']=$r->user()->id;$data['number']='TKT-'.now()->format('Ym').'-'.str_pad((string)(Ticket::max('id')+1),5,'0',STR_PAD_LEFT);$ticket=DB::transaction(function()use($data,$r){$t=Ticket::create($data);TicketStatusHistory::create(['ticket_id'=>$t->id,'user_id'=>$r->user()->id,'to_status'=>'reported','notes'=>'Tiket dibuat']);return $t;});return redirect()->route('tickets.show',$ticket)->with('success','Tiket berhasil dibuat.');}
 public function show(Ticket $ticket){$ticket->load(['reporter','technician','category','location','asset','histories.user']);return view('tickets.show',['ticket'=>$ticket,'technicians'=>User::whereIn('role',['super_admin','ict_head','ict_staff'])->get()]);}
 public function updateStatus(Request $r,Ticket $ticket){$data=$r->validate(['status'=>'required|in:reported,accepted,in_progress,completed,verified','technician_id'=>'nullable|exists:users,id','notes'=>'nullable|max:2000','resolution'=>'nullable|max:5000']);$old=$ticket->status;$update=['status'=>$data['status']];if(array_key_exists('technician_id',$data))$update['technician_id']=$data['technician_id'];if(isset($data['resolution']))$update['resolution']=$data['resolution'];if($data['status']==='accepted')$update['accepted_at']=now();if($data['status']==='completed')$update['completed_at']=now();if($data['status']==='verified')$update['verified_at']=now();DB::transaction(function()use($ticket,$update,$old,$data,$r){$ticket->update($update);TicketStatusHistory::create(['ticket_id'=>$ticket->id,'user_id'=>$r->user()->id,'from_status'=>$old,'to_status'=>$data['status'],'notes'=>$data['notes']??null]);});return back()->with('success','Status tiket diperbarui.');}
}
